LogEntry
The structure of a log event.
interface LogEntry {
  /** Unique event identifier */
  id: string;

  /** ISO 8601 timestamp */
  timestamp: string;

  /** Log level */
  level: string;

  /** Logger scope/namespace */
  scope: string;

  /** Log message */
  message: string;

  /** Optional tags */
  tags?: string[];

  /** Optional state snapshot */
  state?: Record&lt;string, any&gt;;

  /** Optional causing event ID */
  cause?: string;

  /** Environment info */
  env?: {
    platform?: string;
    userAgent?: string;
    url?: string;
  };

  /** Source location */
  callsite?: {
    file?: string;
    line?: number;
    column?: number;
    function?: string;
  };
}


SatoriConfig
Complete configuration interface.
