      tags: [&#x27;login&#x27;, &#x27;security&#x27;, &#x27;success&#x27;],
      state: { username }
    });
    return true;
  }

  authLogger.warn(&#x27;Login failed&#x27;, { 
    tags: [&#x27;login&#x27;, &#x27;security&#x27;, &#x27;failure&#x27;],
    state: { username }
  });
  return false;
}


